446: function HANDLE:SetPoint(point, relframe, relpoint, xofs, yofs)
447: 	if (type(relpoint) == "number") then
448: 		relpoint, xofs, yofs = nil, relpoint, xofs;
449: 	end
450: 	if (relpoint == nil) then
451: 		relpoint = point;
452: 	end
453: 	if ((xofs == nil) and (yofs == nil)) then
454: 		xofs, yofs = 0, 0;
455: 	else
456: 		xofs, yofs = tonumber(xofs), tonumber(yofs);
457: 	end
458: 	if (not _set_points[point]) then
459: 		error("Invalid point '" .. tostring(point) .. "'");
460: 		return;
461: 	end
462: 	if (not _set_points[relpoint]) then
463: 		error("Invalid relative point '" .. tostring(relpoint) .. "'");
464: 		return;
465: 	end
466: 	if (not (xofs and yofs)) then
467: 		error("Invalid offset");
468: 		return
469: 	end
470: 
471: 	local frame = GetHandleFrame(self);
472: 
473: 	local realrelframe = nil;
474: 	if (type(relframe) == "userdata") then
475: 		-- **MUST** be protected
476: 		realrelframe = GetFrameHandleFrame(relframe, true, true);
477: 		if (not realrelframe) then
478: 			error("Invalid relative frame handle");
479: 			return;
480: 		end
481: 	elseif ((relframe == nil) or (relframe == "$screen")) then
482: 		realrelframe = nil;
483: 	elseif (relframe == "$cursor") then
484: 		local cx, cy = GetCursorPosition();
485: 		local eff = LOCAL_CHECK_Frame.GetEffectiveScale(frame);
486: 		xofs = xofs + (cx / eff);
487: 		yofs = yofs + (cy / eff);
488: 		relpoint = "BOTTOMLEFT";
489: 		realrelframe = nil;
490: 	elseif (relframe == "$parent") then
491: 		realrelframe = LOCAL_CHECK_Frame.GetParent(frame);
492: 	else
493: 		error("Invalid relative frame id '" .. tostring(relframe) .. "'");
494: 		return;
495: 	end
496: 
497: 	LOCAL_CHECK_Frame.SetPoint(frame, point, realrelframe, relpoint, xofs, yofs);
498: end
